import { build } from 'esbuild';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const sourceRoot = join(here, '..', 'src');
const output = join(sourceRoot, 'main.bundle.js');

await build({
  entryPoints: [join(sourceRoot, 'main.js')],
  outfile: output,
  bundle: true,
  format: 'iife',
  platform: 'browser',
  // CodeMirror's Unicode-aware lexer requires the property-escape support in
  // WebView/Chromium 64. MainActivity shows a native upgrade message below
  // that floor; src/compat.js fills later convenience APIs.
  target: ['chrome64'],
  charset: 'utf8',
  minify: false,
  sourcemap: false,
  legalComments: 'eof',
  logLevel: 'info',
  banner: { js: '/* PythonA offline browser/WebView bundle. Generated by esbuild. */' }
});

console.log(`wrote ${output} (single-file offline bundle)`);
